WITH kept_keys AS (SELECT level, dept_id FROM employees EXCEPT DISTINCT SELECT level, dept_id FROM employees WHERE UPPER(TRIM(email)) = 'HENRY@STARTUP.IO'), verified AS (SELECT s.* FROM employees s JOIN kept_keys k ON s.level = k.level AND s.dept_id = k.dept_id) SELECT s.id, s.full_name, s.email, s.dept_id, s.manager_id, s.job_title, s.salary, s.hire_date, s.is_remote, CASE WHEN job_title RLIKE '^(Analyst|Intern)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS job_title_zone, (SELECT MIN(x.salary) FROM employees x WHERE x.manager_id = s.manager_id) AS min_employee_salary FROM verified s
